function mean(a){ return a.reduce(function(s,x){return s+x;},0)/a.length; }
function stdev(a){ var m=mean(a); return Math.sqrt(a.reduce(function(s,x){return s+(x-m)*(x-m);},0)/(a.length-1)); }
function quantileSorted(arr, q){ var n=arr.length; if(n===0) return NaN; var pos=(n-1)*q; var lo=Math.floor(pos), hi=Math.ceil(pos); if(lo===hi) return arr[lo]; return arr[lo]+(arr[hi]-arr[lo])*(pos-lo); }
function detectIQR(arr, k){ k=(k==null)?1.5:k; var a=arr.slice().sort(function(x,y){return x-y;}); var q1=quantileSorted(a,0.25), q3=quantileSorted(a,0.75); var iqr=q3-q1; var lo=q1-k*iqr, hi=q3+k*iqr; return a.filter(function(v){return v<lo||v>hi;}); }
function detectZ(arr, zth){ zth=(zth==null)?3:zth; var m=mean(arr), s=stdev(arr); if(s===0) return []; return arr.filter(function(v){return Math.abs((v-m)/s)>zth;}); }
var EXPORTS = { detectIQR:detectIQR, detectZ:detectZ, mean:mean, stdev:stdev };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
